// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }

    // Fuzz the amount to AdjustBetAmounts. We want a general rule: calling AdjustBetAmounts(amount)
    // sets betLimit == amount (reference) — the mutant which does betLimit = betLimit + amount will violate
    // this when the contract's current betLimit is nonzero (or when amount is nonzero and initial was 0 but
    // multiple calls differ). We keep domain wide: any uint256 amount.
    function testFuzz_property(uint256 amount) public {
        // Ensure we call as owner (setUp deployer is owner). No other constraints.

        // Call AdjustBetAmounts with fuzzed amount
        // capture whether call succeeds (it should)
        bool ok;
        try c.AdjustBetAmounts(amount) {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference guarantees the betLimit equals the provided amount after the call.
        // This is the single assertion reading c's public getter. The mutant (which increments)
        // will make this assertion fail for some amounts (e.g., when prior betLimit != 0 or after repeated calls),
        // so the fuzzer can find a counterexample.
        assertTrue(ok && c.currentBetLimit() == amount);
    }
}

