pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this), 0); }

    // fuzzed inputs: newLimit is the desired bet limit to set by caller; caller is the address attempting to call AdjustBetAmounts
    function testFuzz_property(uint256 newLimit, address caller) public {
        // Keep wide domain but avoid zero-address for caller to make prank meaningful
        vm.assume(caller != address(0));

        // Ensure caller has some ETH so if AdjustBetAmounts in some variant were payable it wouldn't fail (defensive)
        vm.deal(caller, 1 ether);

        // Record original betLimit as seen on reference
        uint256 original = c.currentBetLimit();

        // Attempt to call AdjustBetAmounts as the fuzzed caller
        bool ok;
        vm.prank(caller);
        try c.AdjustBetAmounts(newLimit) {
            ok = true;
        } catch {
            ok = false;
        }

        // After call, read betLimit from contract
        uint256 after = c.currentBetLimit();

        // General rule (single assertion): On the reference contract only the owner (deployer/address(this)) can change betLimit,
        // so for ANY caller different from the owner the betLimit must remain equal to original. The mutant removes the owner check
        // and therefore will allow some caller to change betLimit (test will fail on mutant for some inputs).
        if (caller != address(this)) {
            // for non-owner callers, the reference MUST keep betLimit unchanged regardless of newLimit
            assertTrue(after == original);
        } else {
            // if caller is the owner, the reference allows change; ensure behavior is consistent (either changed to newLimit or unchanged)
            // but we must assert a property that holds for reference for ALL inputs: owner can set betLimit to newLimit.
            // So require that if owner called, the betLimit equals newLimit.
            assertTrue(after == newLimit);
        }
    }
}

