pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this), 0); }

    // Fuzzed parameter: an address that will act as the caller. The deciding value is whether it's the owner.
    function testFuzz_property(address caller) public {
        // Keep domain wide but restrict to non-zero addresses (owner in setUp is address(this)).
        vm.assume(caller != address(0));

        bool ok;
        // The behavior difference is only observable when the owner calls OpenToThePublic().
        // We let the fuzzer choose `caller`. If caller equals the owner (address(this)), the reference
        // will set openToPublic = true; the mutant will set it to false. We check the flag after the call.
        if (caller == address(this)) {
            // owner call: should succeed and set the flag (reference: true)
            try c.OpenToThePublic() {
                ok = c.hasPlayerWagered(address(0)) // dummy read to use c before final assert
                    ? true
                    : true; // no-op to keep single assert later
            } catch {
                ok = false;
            }
            // Now read the flag via a public view: there is no public getter for openToPublic (it's private),
            // but the contract exposes behavior dependent on that flag: calling wager() requires isOpenToPublic
            // which reverts if openToPublic is false. We'll attempt a call to wager() from an EOA that is the caller.
            // Prepare funds and make the call, catching success/failure.
            vm.deal(caller, 1 ether);
            vm.prank(caller);
            bool wagerOk;
            try c.wager{value: 0.000000000000000001 ether}() { // send a tiny value; contract requires betLimit==0 from setUp
                wagerOk = true;
            } catch {
                wagerOk = false;
            }
            // The reference sets openToPublic = true, so wager should succeed (betLimit was constructed as 0);
            // The mutant sets openToPublic = false, so wager will revert and wagerOk will be false.
            // Single assertion: when caller is the owner, wagerOk must be true on the correct contract; the mutant will fail for some input (owner).
            assertTrue(wagerOk);
        } else {
            // Non-owner calls: OpenToThePublic is protected by onlyOwner and should revert; ensure it reverts.
            try c.OpenToThePublic() {
                ok = true;
            } catch {
                ok = false;
            }
            // non-owner must not be able to open to public, so ok should be false
            assertTrue(!ok);
        }
    }
}

