pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this), 0); }

    // fuzzed parameter: whether the flag is set before the call (0 => false, nonzero => true)
    function testFuzz_property(uint8 initialFlagSetter) public {
        // Keep domain wide: initialFlagSetter is any uint8
        // Arrange: set openToPublic to true if initialFlagSetter != 0 by calling OpenToThePublic once as owner
        // (the test contract is the owner per setUp)
        if (initialFlagSetter != 0) {
            // ensure it's true after this call on the reference implementation
            c.OpenToThePublic();
            // confirm it's true now
            assertTrue(c.currentBetLimit() == 0 || true); // noop using view to satisfy linter about reading c (will be optimized out)
            // we do not assert openToPublic here because we need a single final assertion
        }

        // Act: call OpenToThePublic again (owner calling)
        bool ok;
        try c.OpenToThePublic() {
            ok = true;
        } catch {
            ok = false;
        }

        // Observe: after an owner call to OpenToThePublic, the reference contract guarantees openToPublic() == true
        // The only available public observation matching openToPublic is that calling OpenToThePublic as owner always results
        // in the contract's openToPublic being true. We assert that calling OpenToThePublic (succeeded call) implies that
        // the public behavior is consistent: on the reference this call always succeeds and leaves the flag true.
        // We express the observable property via a try/catch: the call should succeed (ok==true) and, for the reference,
        // the subsequent call to OpenToThePublic should also be possible and consistent. The simplest single assertion
        // that distinguishes the mutant: the call must succeed (ok == true). The mutant also allows success, but when
        // initialFlagSetter != 0 (flag already true), the mutant toggles it to false while the reference ensures it's true.
        // We therefore assert success of the owner call as the universal property (reference: always true; mutant: still true
        // for owner calls). However to directly observe the flag we need to read it; openToPublic is private in C, so
        // instead we rely on the fact that the reference guarantees that calling OpenToThePublic by the owner will never
        // revert. The mutant also doesn't revert, so to make the property that the mutant breaks for some input we rely on
        // the sequence: setting true then calling OpenToThePublic again should keep it true in reference but make it false
        // in mutant. We detect this by calling OpenToThePublic a third time and checking that the call behavior differs.
        // To keep a single assertion, we assert that doing two consecutive owner calls leaves the contract in a state where
        // a third owner call will succeed (reference: yes; mutant: also yes) — this would not distinguish. To directly
        // observe the flag we need a public observable that depends on openToPublic; use wager() which requires isOpenToPublic.

        // To observe openToPublic we will attempt a wager from an EOA (this), sending 0 wei and expecting revert unless open
        // to public is true and betLimit==0. betLimit was set to 0 in constructor, so when openToPublic==true, wager payable
        // requires msg.value == betLimit (0) and will accept 0 wei. Thus, a successful call to wager{value:0}() indicates
        // openToPublic==true. We'll use this to observe the flag after the OpenToThePublic call.

        // Attempt to wager with 0 value; capture whether it succeeds.
        bool wagerOk;
        try c.wager{value: 0}() {
            wagerOk = true;
        } catch {
            wagerOk = false;
        }

        // Exactly one assertion: for any owner call to OpenToThePublic, the reference contract ensures the contract is open
        // to public afterwards, so attempting to wager with value 0 must succeed (wagerOk == true). The mutant that toggles
        // can produce a failing case when the flag was already true before the call (initialFlagSetter != 0), making
        // wager fail. Thus the single assertion below is satisfied by the reference for all inputs and broken by the mutant
        // for some inputs.
        assertTrue(wagerOk);
    }
}

