        vm.assume(actor != address(0));
        vm.assume(actor != address(this));

        // Bound deposit to a reasonable range including values <= betLimit and > betLimit
        deposit = bound(deposit, 0, 10 ether);

        // Ensure contract is open to public so wager() can be called
        vm.prank(address(this));
        c.OpenToThePublic();

        // Fund the actor so they can send ETH in the fuzzed deposit
        vm.deal(actor, deposit + 1 ether);

        // Actor attempts to wager with the fuzzed deposit amount
        bool ok;
        vm.prank(actor);
        try c.wager{value: deposit}() {
            ok = true;
        } catch {
            ok = false;
        }

        // Single assertion: if the wager call succeeded then the recorded wagers[actor] must equal the configured betLimit
        // This holds for the reference (which requires msg.value == betLimit) for all inputs; the mutant (msg.value <= betLimit)
        // allows smaller deposits to succeed and thus records wagers[actor] != betLimit for some inputs, breaking this assertion.
        if (ok) {
            // read wagers via the public view hasPlayerWagered and winnersPot / ethBalance are allowed; but we need the exact stored wager amount.
            // The contract does not expose wagers mapping directly; however, hasPlayerWagered tells us whether wagers[actor] > 0.
            // To observe the stored wager amount, we can assert that hasPlayerWagered(actor) is true and that the contract's winnersPot
            // (which is address(this).balance/2) will reflect consistent behavior only if the stored wager equals betLimit. But to follow the rules strictly
            // we must read c.currentBetLimit() which is public and compare to the recorded wager; since wagers mapping is private, we infer via behavior:
            // In the reference contract, the only way ok==true is when deposit == betLimit, so deposit == c.currentBetLimit().
            // Thus assert that deposit equals the contract's configured betLimit.
            uint256 limit = c.currentBetLimit();
            assertTrue(deposit == limit);
        } else {
            // If the call reverted, nothing to assert beyond that we didn't record a wager. We still must have exactly one assertTrue in the function,
            // so when ok==false assert a tautology about the contract state that always holds for the reference: no player wager recorded.
            // Use hasPlayerWagered(actor) which must be false after a reverted call.
            assertTrue(!c.hasPlayerWagered(actor));
        }
    }
}

